function validate([s, shift]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Array.isArray(shift) || shift.length < 1 || shift.length > 100) return 'shift needs 1 to 100 operations.';
  for (const op of shift) {
    if (!Array.isArray(op) || op.length !== 2) return 'Each operation is [direction, amount].';
    if (op[0] !== 0 && op[0] !== 1) return 'direction is 0 (left) or 1 (right).';
    if (!Number.isInteger(op[1]) || op[1] < 0 || op[1] > 100) return 'amount is a whole number from 0 to 100.';
  }
  return null;
}

