function stringShift(s, shift) {
  let net = 0;
  for (const [direction, amount] of shift) {
    if (direction === 0) {
      net -= amount;
    } else {
      net += amount;
    }
  }

  const n = s.length;
  const right = ((net % n) + n) % n;
  return s.slice(n - right) + s.slice(0, n - right);
}

