function stringShift(s, shift) {
  const chars = s.split('');
  for (const [direction, amount] of shift) {
    for (let step = 0; step < amount; step++) {
      if (direction === 0) chars.push(chars.shift());
      else chars.unshift(chars.pop());
    }
  }
  return chars.join('');
}

