function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  const alphabet = rand() < 0.3 ? 2 : 26;
  const s = Array.from({ length: n }, () => letters[Math.floor(rand() * alphabet)]).join('');
  const m = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const top = size === 'large' ? 100 : rand() < 0.5 ? 3 : 100;
  const leftBias = rand();
  const shift = Array.from({ length: m }, () => [rand() < leftBias ? 0 : 1, Math.floor(rand() * (top + 1))]);
  return [s, shift];
}
